    "v10": "repeat_count"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "command token whose extension supplies the data size"
    },
    {
      "offset": 4,
      "meaning": "token string parsed as the write address"
    },
    {
      "offset": 8,
      "meaning": "token string parsed as the write value"
    },
    {
      "offset": 12,
      "meaning": "optional token string parsed as the repeat count"
    }
  ]
